test('opening the personal library only reads local records and exposes unique, accessible controls',async()=>{
 const f=fixture({connected:false,items:[]});await settle(()=>f.el('page').getAttribute('aria-busy')==='false');assert.ok(f.requests.every(request=>request.method==='GET'));assert.equal(f.el('sync').disabled,true);assert.equal(f.el('profile-settings').hasAttribute('open'),true);assert.equal(f.registrations[0].durable,false);
 const ids=[...f.document.querySelectorAll('[id]')].map(node=>node.id);assert.equal(new Set(ids).size,ids.length);assert.equal(f.document.querySelectorAll('[data-navigation-page]').length,6);assert.ok(f.document.querySelector('[data-navigation-page="douban"][href="/life/douban"]'));assert.equal(f.document.querySelector('.sidebar-utilities [data-navigation-page="douban"]'),null);assert.match(f.document.body.textContent??'',/不接收豆瓣密码或 Cookie/);
});

test('the shelf keeps sources and comments in details while opening and closing tool sections never writes or connects',async()=>{
 const f=fixture({extension:true});await settle(()=>f.el('list').children.length===1);assert.equal(f.el('tools-dialog').hasAttribute('open'),false);assert.equal(f.el('list').textContent?.includes('合成个人短评'),false);assert.equal(f.el('list').textContent?.includes('公开收藏页'),false);assert.equal(f.el('list').textContent?.includes('来源 mine'),false);assert.match(f.el('list').textContent??'',/我的 4 \/ 5/);assert.ok(f.el('list').querySelector('.db-cover img'));
 f.click('tools-open');for(const section of ['public','import','manage','browser']){f.document.querySelector('[data-douban-tools-tab="'+section+'"]')!.dispatchEvent(new f.window.Event('click',{bubbles:true}));assert.equal(f.el('tools-dialog').dataset.section,section);}f.click('tools-close');assert.equal(f.el('tools-dialog').hasAttribute('open'),false);assert.equal(f.extensionCalls.length,0);assert.ok(f.requests.every(request=>request.method==='GET'));f.el('list').querySelector('[data-douban-open]')!.dispatchEvent(new f.window.Event('click',{bubbles:true}));assert.match(f.el('detail-body').textContent??'',/合成个人短评/);assert.match(f.el('detail-body').textContent??'',/来源主页mine/);
});

test('category chips share query and source counts, preserve history and focus, and safely clear filters without touching the connection',async()=>{
 const f=fixture({items:[{...record,title:'共同电影'},{...record,domain:'book',kind:'book',subjectId:'23456',title:'共同图书'},{...record,domain:'book',kind:'book',subjectId:'34567',title:'共同旧图书',profileId:'older'},{...record,domain:'music',kind:'music',subjectId:'45678',title:'另一首音乐'}]});await settle(()=>f.el('list').children.length===4);let navEvents=0;f.window.addEventListener('jiashu-navigation',()=>{navEvents++;});f.input('query','共同');f.submit('search-form');await settle(()=>f.el('list').children.length===3);f.change('scope','current');await settle(()=>f.el('list').children.length===2);const book=f.el('kind-chips').querySelector('[data-douban-kind="book"]')! as HTMLElement;book.focus();book.dispatchEvent(new f.window.Event('click',{bubbles:true}));await settle(()=>f.el('kind').value==='book'&&f.el('list').children.length===1&&f.document.activeElement?.getAttribute('data-douban-kind')==='book');assert.match(f.location.search,/kind=book/);assert.match(f.location.search,/profile=current/);assert.equal(f.el('query').value,'共同');assert.equal(f.el('kind-chips').querySelector('[aria-pressed="true"]')?.getAttribute('data-douban-kind'),'book');assert.equal(f.el('kind-chips').querySelector('[data-douban-kind="all"] .db-chip-count')?.textContent,'2');assert.equal(f.el('kind-chips').querySelector('[data-douban-kind="movie"] .db-chip-count')?.textContent,'1');f.history.back();await settle(()=>f.el('kind').value===''&&f.el('list').children.length===2);f.history.forward();await settle(()=>f.el('kind').value==='book'&&f.el('list').children.length===1);
 f.input('query','不存在的名称');f.submit('search-form');await settle(()=>f.el('empty').hidden===false);assert.match(f.el('empty').querySelector('h3')?.textContent??'',/没有找到/);assert.equal(f.el('empty-cta').hidden,true);const connection=structuredClone(f.connection());f.el('reset-filters').focus();f.click('reset-filters');await settle(()=>f.el('list').children.length===4&&f.document.activeElement?.id==='douban-query');assert.equal(f.location.search,'');assert.equal(f.el('scope').value,'all');assert.equal(f.el('kind').value,'');assert.equal(f.el('query').value,'');assert.deepEqual(f.connection(),connection);assert.ok(navEvents>=5);assert.ok(f.requests.every(request=>request.method==='GET'));
});

test('long detail content expands locally, manual classification keeps its guard, and closing restores a newly rendered card',async()=>{
 const f=fixture({items:[{...record,details:{summary:'这是一段很长的简介。'.repeat(50),cast:Array.from({length:12},(_,index)=>'演员'+index)}},{...record,domain:'music',kind:'music',subjectId:'23456',details:{tracks:Array.from({length:12},(_,index)=>'曲目'+index)}}]});await settle(()=>f.el('list').children.length===2);f.el('list').querySelector('[data-douban-open="0"]')!.dispatchEvent(new f.window.Event('click',{bubbles:true}));for(const key of ['summary','cast']){const button=f.el('detail-body').querySelector('[data-douban-expand="'+key+'"]')!;assert.equal(button.getAttribute('aria-expanded'),'false');button.dispatchEvent(new f.window.Event('click',{bubbles:true}));assert.equal(button.getAttribute('aria-expanded'),'true');assert.equal(f.el('detail-body').querySelector('[data-douban-long="'+key+'"]')?.getAttribute('data-expanded'),'true');}assert.ok(f.el('detail-body').querySelector('[data-douban-detail-cover]'));assert.ok(f.requests.every(request=>request.method==='GET'));f.change('classification-kind','series');const cancel=new f.window.Event('cancel',{cancelable:true});f.el('detail-dialog').dispatchEvent(cancel);assert.equal(cancel.defaultPrevented,true);assert.equal(f.el('detail-dialog').hasAttribute('open'),true);assert.equal(f.el('classification-kind').value,'series');assert.equal(f.confirmations.length,1);f.submit('classification-form');await settle(()=>f.el('classification-status').textContent==='分类已保存为电视剧。');f.click('detail-close');assert.equal(f.el('detail-dialog').hasAttribute('open'),false);assert.equal(f.document.activeElement?.getAttribute('data-douban-open'),'0');
 f.el('list').querySelector('[data-douban-open="1"]')!.dispatchEvent(new f.window.Event('click',{bubbles:true}));const tracks=f.el('detail-body').querySelector('[data-douban-expand="tracks"]')!;assert.equal(tracks.getAttribute('aria-expanded'),'false');tracks.dispatchEvent(new f.window.Event('click',{bubbles:true}));assert.equal(tracks.getAttribute('aria-expanded'),'true');assert.equal(f.el('detail-body').querySelectorAll('[data-douban-long="tracks"] [data-douban-long-item="extra"]').length,4);assert.equal(f.requests.filter(request=>request.method!=='GET').length,1);
});

test('hidden tool drafts remain active and a paused browser job exposes progress without losing selected files',async()=>{
 const f=fixture({extension:true});await settle(()=>!f.el('browser-sync').disabled);f.completeImport();f.click('tools-open');f.document.querySelector('[data-douban-tools-tab="import"]')!.dispatchEvent(new f.window.Event('click',{bubbles:true}));f.click('tools-close');assert.equal(f.el('workspace-progress').hidden,false);assert.equal(f.el('workspace-progress').dataset.doubanToolsOpen,'import');f.click('workspace-progress');assert.equal(f.el('tools-dialog').dataset.section,'import');const tracked=f.registrations.filter(guard=>['douban-profile-form','douban-import-form','douban-browser-form','douban-reset-form'].includes((guard.form as HTMLElement).id));assert.equal(tracked.length,4);assert.ok(tracked.every(guard=>guard.trackWhenHidden===true&&(guard.isActive as ()=>boolean)()));
 let finish!:(value:unknown)=>void,command!:Record<string,unknown>;f.setExtensionHandler((message,reply)=>{if(message.action==='STEP'){command=message;finish=reply;}else replyExtension(message,reply);});f.document.querySelector('[data-douban-tools-tab="browser"]')!.dispatchEvent(new f.window.Event('click',{bubbles:true}));f.click('browser-sync');await settle(()=>Boolean(finish));f.click('tools-close');assert.equal(f.el('workspace-progress').dataset.doubanToolsOpen,'browser');assert.equal(f.el('workspace-progress').hidden,false);f.click('workspace-progress');assert.equal(f.el('tools-dialog').dataset.section,'browser');f.click('browser-stop');finish({ok:true,data:{runId:command.runId,step:1,items:[{...record,source:'import'}],progress:extensionProgress('running',1,1),done:false}});await settle(()=>f.el('browser-status').textContent?.startsWith('已暂停浏览器同步')===true);f.click('tools-close');assert.equal(f.el('workspace-progress').dataset.doubanToolsOpen,'browser');assert.equal((f.el('import-files') as unknown as HTMLInputElement).files?.length,1);assert.equal(f.el('import-profile').value,'private_owner');f.session.changed=true;assert.ok(tracked.every(guard=>(guard.isActive as ()=>boolean)()===false));
});

